 events:{programId:"refs:programs:one",cycleId:"refs:cycles:optional",kind:["incident","grievance","nonconformity","change"],code:"required",publicSummary:"required",severity:["unknown","low","moderate","high","critical"],occurredAt:"timestamp",receivedAt:"date",status:["received","triage","investigating","response","verification","closed","reopened"],immediateMeasures:"text",notificationObligations:"text",investigation:"text",rootCause:"text",response:"text",requirementIds:"refs:requirements",obligationIds:"refs:monitoringObligations",assertionIds:"refs:assertions",actionIds:"refs:actions",escalation:"text",closureStatement:"text",restricted:"sealed",restrictedProtection:"protected_refs",restrictedOrigin:"case_origin",restrictedAvailable:"boolean",restrictedSha256:"text",lastVerificationId:"text"},
